import { randomUUID } from 'node:crypto';
import { text } from 'drizzle-orm/sqlite-core';

/**
 * Column helpers shared by every table. SQLite has no uuid or timestamp type, so:
 *
 * - ids are TEXT holding a v4 UUID, generated by the app when a row is inserted;
 * - timestamps are TEXT holding `Date.toISOString()` (UTC, fixed width). Strings in that one
 *   format sort in time order, so ORDER BY created_at stays correct. Never store a timestamp
 *   in any other format in these columns: a mixed column sorts wrongly without any error.
 */
export const idColumn = () =>
  text('id')
    .primaryKey()
    .$defaultFn(() => randomUUID());

/** An ISO-8601 UTC timestamp column (nullable unless you add `.notNull()`). */
export const timestampColumn = (name: string) => text(name);

/** `created_at` / `updated_at`, set by the app on insert. */
export const createdAtColumn = () =>
  timestampColumn('created_at')
    .notNull()
    .$defaultFn(() => new Date().toISOString());
export const updatedAtColumn = () =>
  timestampColumn('updated_at')
    .notNull()
    .$defaultFn(() => new Date().toISOString());
